from pathlib import Path
sets={'liste': [('Görsel akış','Büyük fotoğraflı kapaklardan tek sütunda, kesintisiz tarif keşfi.','Airbnb · AllTrails'),('Başparmak ızgarası','Fotoğraflar yukarıda, kategori ve filtreler elinin altında.','Etsy · SideChef'),('Tarif rafları','Gerçek kategori ve süre filtreleri yatay keşif raflarına dönüşür.','Netflix · Disney+'),('Kategori atlası','Solda kategori dizini, sağda o kategoriye ait görsel katalog.','Spotify · Uber Eats')], 'detay':[('Sürükleyici kapak','Fotoğrafla başla; tutma çubuğundan içeriği yukarı çek.','AllTrails · Booking'),('Tarif çalışma alanı','Tarif kimliği yerinde kalır; malzemeler, yapılış ve yorumlar arasında kaydır.','Samsung Food · Headspace'),('Adım akışı','Malzemelerini kontrol et, büyük adım kartlarıyla pişirmeye geç.','SideChef · Nike Training'),('Tarif kumandası','Kapak fotoğrafının altında tek dokunuşla malzeme, adım ve yorumlara ulaş.','Spotify · Amazon')]}
css='''body{margin:0;background:#211E16;color:#fff;font-family:Gilroy,Arial,sans-serif;padding:32px}*{box-sizing:border-box}h1{font-size:28px}a{color:#fff}header{max-width:960px;margin:0 auto 32px}header nav{display:flex;gap:20px;margin-bottom:20px}.gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:40px 24px;max-width:980px;margin:auto}article{min-width:0;display:flex;flex-direction:column;align-items:center}.phone{box-sizing:content-box;width:var(--w,390px);max-width:100%;border:8px solid #56514A;border-radius:32px;overflow:hidden;background:white;height:844px}iframe{width:100%;height:100%;border:0}h2,p,.states{width:var(--w,390px);max-width:100%}h2{font-size:20px;margin:16px 0 8px}p{font-size:15px;line-height:1.4;margin:0 0 8px}.refs{color:#bbb;font-size:13px}.states{display:flex;gap:8px;flex-wrap:wrap}.states a,button{padding:8px 12px;border:1px solid #6F6F6F;border-radius:12px;background:transparent;color:white;font:inherit;cursor:pointer}select{font:inherit;padding:8px} @media(max-width:850px){.gallery{grid-template-columns:1fr}body{padding:20px}.phone{width:min(var(--w,390px),100%)} }'''
for kind,items in sets.items():
    cards=[]
    for letter,(name,idea,refs) in zip('abcd',items):
        file=f'{kind}-{letter}.html'
        states= [('Normal',''),('Yükleniyor','?durum=yukleniyor'),('Boş','?durum=bos'),('Sonuç yok','?q=zzzz')] if kind=='liste' else [('Tam tarif',''),('Besin değerli tarif','?tarif=patates-mucveri-cig-rendelenmis-patatesle-tavada-kizaran-kahvaltilik-mucver')]
        cards.append(f'<article><div class="phone"><iframe title="{name}" src="{file}" loading="lazy"></iframe></div><h2>{letter.upper()} · {name}</h2><p>{idea}</p><p class="refs">{refs}</p><div class="states">'+''.join(f'<a href="{file}{qs}" target="_blank">{label}</a>' for label,qs in states)+'</div></article>')
    Path(f'v3-app/{kind}-secenekleri.html').write_text(f'''<!doctype html><html lang="tr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>DadaGastro · {kind.title()} seçenekleri</title><link rel="stylesheet" href="tokens.css"><style>{css}</style><header><nav><a href="hero-secenekleri.html">Hero</a><a href="liste-secenekleri.html">Liste</a><a href="detay-secenekleri.html">Detay</a></nav><h1>{'Tarif Listesi' if kind=='liste' else 'Tarif Detay'} · dört yaklaşım</h1><p>Aynı veri, aynı işlevler; dört farklı uygulama kurgusu.</p><label>Genişlik <select id="width"><option>360</option><option selected>390</option><option>430</option></select></label></header><main class="gallery">{''.join(cards)}</main><script>document.querySelector('#width').onchange=e=>document.documentElement.style.setProperty('--w',e.target.value+'px')</script></html>''')
